563	def _parse_diff_into_rows(
564	    diff_lines: list[str],
565	    before_lines: list[str] | None = None,
566	    after_lines: list[str] | None = None,
567	    max_expand: int = 20,
568	) -> tuple[list[dict], list[dict]]:
569	    """Parse unified diff lines into aligned left/right rows.
570	
571	    When ``before_lines`` / ``after_lines`` are provided, expand sections
572	    are collected (up to ``max_expand`` lines each direction) for rendering
573	    as native ``<details>`` elements outside the diff table.
574	
575	    Returns
576	    -------
577	    tuple[list[dict], list[dict]]
578	        (visible_rows, expand_sections).  Expand sections have keys:
579	        position ('before'|'after'), hunk_idx, direction, count, lines.
580	    """
581	    import re
582	
583	    # ── Phase 1: parse visible diff rows ──
584	    visible_rows = []
585	    i = 0
586	    left_num = 0
587	    right_num = 0
588	    # Track hunk boundaries: list of (before_start, before_end, after_start, after_end)
589	    hunk_ranges: list[tuple[int, int, int, int]] = []
590	    current_hunk_start_left = 0
591	    current_hunk_start_right = 0
592	
593	    while i < len(diff_lines):
594	        line = diff_lines[i]
595	
596	        if line.startswith("---") or line.startswith("+++"):
597	            i += 1
598	            continue
599	
600	        if line.startswith("@@"):
601	            # Save previous hunk range
602	            if hunk_ranges or visible_rows:
603	                hunk_ranges.append(
604	                    (
605	                        current_hunk_start_left,
606	                        left_num,
607	                        current_hunk_start_right,
608	                        right_num,
609	                    )
610	                )
611	            m = re.match(r"@@ -(\d+)", line)
612	            if m:
613	                left_num = int(m.group(1)) - 1
614	                current_hunk_start_left = left_num
615	            m2 = re.match(r"@@ -\d+(?:,\d+)? \+(\d+)", line)
616	            if m2:
617	                right_num = int(m2.group(1)) - 1
618	                current_hunk_start_right = right_num
619	            visible_rows.append({"type": "hunk", "left": line, "right": "", "left_num": None, "right_num": None})
620	            i += 1
621	            continue
622	
623	        if line.startswith("-"):
624	            if i + 1 < len(diff_lines) and diff_lines[i + 1].startswith("+"):
625	                left_num += 1
626	                right_num += 1
627	                visible_rows.append(
628	                    {
629	                        "type": "pair",
630	                        "left": line[1:],
631	                        "right": diff_lines[i + 1][1:],
632	                        "left_num": left_num,
633	                        "right_num": right_num,
634	                    }
635	                )
636	                i += 2
637	                continue
638	            else:
639	                left_num += 1
640	                visible_rows.append({"type": "del", "left": line[1:], "right": "", "left_num": left_num, "right_num": None})
641	                i += 1
642	                continue
643	
644	        if line.startswith("+"):
645	            right_num += 1
646	            visible_rows.append({"type": "add", "left": "", "right": line[1:], "left_num": None, "right_num": right_num})
647	            i += 1
648	            continue
649	
650	        # Context line
651	        left_num += 1
652	        right_num += 1
653	        visible_rows.append(
654	            {
655	                "type": "ctx",
656	                "left": line[1:] if len(line) > 0 else "",
657	                "right": line[1:] if len(line) > 0 else "",
658	                "left_num": left_num,
659	                "right_num": right_num,
660	            }
661	        )
662	        i += 1
663	
664	    # Save last hunk range
665	    if current_hunk_start_left or visible_rows:
666	        hunk_ranges.append(
667	            (
668	                current_hunk_start_left,
669	                left_num,
670	                current_hunk_start_right,
671	                right_num,
672	            )
673	        )
674	
675	    # ── Phase 2: collect expand sections if full scripts provided ──
676	    if before_lines is None or after_lines is None or not hunk_ranges:
677	        return visible_rows, []
678	
679	    expand_sections: list[dict] = []
680	    hunk_idx = 0
681	
682	    for row in visible_rows:
683	        if row["type"] == "hunk":
684	            if hunk_idx < len(hunk_ranges):
685	                bl_start, bl_end, al_start, al_end = hunk_ranges[hunk_idx]
686	
687	                # ── Expand UP: lines before this hunk ──
688	                if hunk_idx > 0:
689	                    prev_bl_end = hunk_ranges[hunk_idx - 1][1]
690	                    prev_al_end = hunk_ranges[hunk_idx - 1][3]
691	                else:
692	                    prev_bl_end = 0
693	                    prev_al_end = 0
694	
695	                up_start_left = max(prev_bl_end, bl_start - max_expand)
696	                up_start_right = max(prev_al_end, al_start - max_expand)
697	                up_count_left = bl_start - up_start_left
698	                up_count_right = al_start - up_start_right
699	
700	                if up_count_left > 0 or up_count_right > 0:
701	                    max_up = max(up_count_left, up_count_right)
702	                    lines = []
703	                    for j in range(max_up):
704	                        ln_left = up_start_left + j + 1 if j < up_count_left else None
705	                        ln_right = up_start_right + j + 1 if j < up_count_right else None
706	                        left_content = before_lines[ln_left - 1] if ln_left and ln_left <= len(before_lines) else ""
707	                        right_content = after_lines[ln_right - 1] if ln_right and ln_right <= len(after_lines) else ""
708	                        lines.append({"left": left_content, "right": right_content, "left_num": ln_left, "right_num": ln_right})
709	                    expand_sections.append(
710	                        {
711	                            "position": "before",
712	                            "hunk_idx": hunk_idx,
713	                            "direction": "up",
714	                            "count": max_up,
715	                            "lines": lines,
716	                        }
717	                    )
718	
719	            hunk_idx += 1
720	
721	    # ── Expand DOWN after last hunk ──
722	    if hunk_ranges:
723	        bl_start, bl_end, al_start, al_end = hunk_ranges[-1]
724	        down_count_left = min(max_expand, len(before_lines) - bl_end)
725	        down_count_right = min(max_expand, len(after_lines) - al_end)
726	
727	        if down_count_left > 0 or down_count_right > 0:
728	            max_down = max(down_count_left, down_count_right)
729	            lines = []
730	            for j in range(max_down):
731	                ln_left = bl_end + j + 1 if j < down_count_left else None
732	                ln_right = al_end + j + 1 if j < down_count_right else None
733	                left_content = before_lines[ln_left - 1] if ln_left and ln_left <= len(before_lines) else ""
734	                right_content = after_lines[ln_right - 1] if ln_right and ln_right <= len(after_lines) else ""
735	                lines.append({"left": left_content, "right": right_content, "left_num": ln_left, "right_num": ln_right})
736	            expand_sections.append(
737	                {
738	                    "position": "after",
739	                    "hunk_idx": len(hunk_ranges) - 1,
740	                    "direction": "down",
741	                    "count": max_down,
742	                    "lines": lines,
743	                }
744	            )
745	
746	    return visible_rows, expand_sections
747	
