749	def _inline_highlight(old_text: str, new_text: str) -> tuple[str, str]:
750	    """Compute word-level inline highlights between old and new text.
751	
752	    Returns (old_html, new_html) with <span class='hl'> wrapping changed words.
753	    """
754	    import difflib as _dl
755	
756	    old_words = old_text.split(" ")
757	    new_words = new_text.split(" ")
758	
759	    sm = _dl.SequenceMatcher(None, old_words, new_words)
760	
761	    old_parts = []
762	    new_parts = []
763	
764	    for tag, i1, i2, j1, j2 in sm.get_opcodes():
765	        old_chunk = " ".join(old_words[i1:i2])
766	        new_chunk = " ".join(new_words[j1:j2])
767	        if tag == "equal":
768	            old_parts.append(html_module.escape(old_chunk))
769	            new_parts.append(html_module.escape(new_chunk))
770	        else:
771	            if old_chunk:
772	                old_parts.append(f'<span class="hl">{html_module.escape(old_chunk)}</span>')
773	            if new_chunk:
774	                new_parts.append(f'<span class="hl">{html_module.escape(new_chunk)}</span>')
775	
776	    return " ".join(old_parts), " ".join(new_parts)
777	
778	
779	def _rows_to_html_table(rows: list[dict]) -> str:
780	    """Convert parsed diff rows into a Beyond Compare style side-by-side HTML table."""
781	    table_rows = []
782	
783	    for row in rows:
784	        ln_left = str(row["left_num"]) if row["left_num"] is not None else ""
785	        ln_right = str(row["right_num"]) if row["right_num"] is not None else ""
786	
787	        if row["type"] == "hunk":
788	            table_rows.append(f'<tr class="hunk"><td colspan="5">{html_module.escape(row["left"])}</td></tr>')
789	
790	        elif row["type"] == "ctx":
791	            left_esc = html_module.escape(row["left"])
792	            right_esc = html_module.escape(row["right"])
793	            table_rows.append(
794	                f'<tr class="ctx">'
795	                f'<td class="ln">{ln_left}</td><td class="code">{left_esc}</td>'
