974	                f'<button class="copy-btn" data-copy-target="{before_id}">📋 Copy</button>'
975	                f'<span class="panel-label" style="margin-left:24px">After</span>'
976	                f'<button class="copy-btn" data-copy-target="{after_id}">📋 Copy</button>'
977	                f"</div>"
978	                f"{''.join(hunk_blocks)}"
979	                f"</div>"
980	            )
981	        else:
982	            # Unchanged: show full IR content with copy button
983	            body = (
984	                f'<div class="full-content">'
985	                f'<div class="panel-bar">'
986	                f'<span class="panel-label">IR (unchanged)</span>'
987	                f'<button class="copy-btn" data-copy-target="{before_id}">📋 Copy</button>'
988	                f"</div>"
