1030	def pass_diff(
1031	    func_or_mod,
1032	    passes,
1033	    *,
1034	    mode: str = "terminal",
1035	    context: int = 3,
1036	    html_path: str = "pass_diff_report.html",
1037	) -> list[dict]:
1038	    """Compare IR before and after each pass in a chain.
1039	
1040	    Parameters
1041	    ----------
1042	    func_or_mod : PrimFunc or IRModule
1043	        The starting IR.
1044	    passes : Pass or list[Pass] or list[tuple[str, Pass]]
1045	        A single pass, a list of passes, or a list of (name, pass) pairs.
1046	        If passes are not named, a default name is derived from the pass object.
1047	    mode : {"terminal", "html", "both"}
1048	        Output mode. ``"terminal"`` prints colored diff to stdout.
1049	        ``"html"`` generates an HTML file. ``"both"`` does both.
1050	    context : int
1051	        Number of context lines in the unified diff (default 3).
1052	    html_path : str
1053	        Output path for HTML report (default ``pass_diff_report.html``).
1054	
1055	    Returns
1056	    -------
1057	    list[dict]
1058	        One entry per pass step, each containing:
1059	        ``name``, ``before_script``, ``after_script``, ``diff_lines``,
1060	        ``insertions``, ``deletions``, ``changed``.
1061	    """
1062	    mode = str(mode).strip().lower()
1063	    if mode not in ("terminal", "html", "both"):
1064	        raise ValueError(f"mode must be one of 'terminal', 'html', 'both', got {mode!r}")
1065	
1066	    # Normalize passes to list of (name, pass)
1067	    if not isinstance(passes, (list, tuple)):
1068	        passes = [passes]
1069	
1070	    named_passes: list[tuple[str, object]] = []
1071	    for p in passes:
1072	        if isinstance(p, (list, tuple)) and len(p) == 2:
1073	            named_passes.append((str(p[0]), p[1]))
1074	        else:
1075	            name = type(p).__name__
1076	            named_passes.append((name, p))
1077	
1078	    total = len(named_passes)
1079	    mod = _to_mod(func_or_mod)
1080	    results: list[dict] = []
1081	
1082	    for step_idx, (name, p) in enumerate(named_passes, 1):
1083	        before_script = _get_script(mod)
1084	
1085	        # Apply pass
1086	        mod = p(mod)
1087	
1088	        after_script = _get_script(mod)
1089	
1090	        before_lines = before_script.splitlines()
1091	        after_lines = after_script.splitlines()
1092	        diff_lines = _compute_diff(before_lines, after_lines, context)
1093	        insertions, deletions = _count_changes(diff_lines)
1094	        changed = insertions > 0 or deletions > 0
1095	
1096	        step_result = {
1097	            "name": name,
1098	            "before_script": before_script,
1099	            "after_script": after_script,
1100	            "diff_lines": diff_lines,
1101	            "insertions": insertions,
1102	            "deletions": deletions,
1103	            "changed": changed,
1104	        }
1105	        results.append(step_result)
1106	
1107	        # Terminal output
1108	        if mode in ("terminal", "both"):
1109	            _print_step_header(step_idx, total, name)
1110	            _print_colored_diff(diff_lines)
1111	            if changed:
1112	                print(f"\n  {_DIM}>>> +{insertions} insertion(s), -{deletions} deletion(s){_RESET}")
1113	            else:
1114	                print(f"\n  {_DIM}>>> (no changes){_RESET}")
1115	
1116	    # HTML output
1117	    if mode in ("html", "both"):
1118	        _generate_html(results, html_path)
1119	        if mode == "html":
1120	            print(f"HTML report written to: {html_path}")
1121	        else:
1122	            print(f"\nHTML report also written to: {html_path}")
1123	
1124	    return results
