    cursor: pointer;
    font-family: inherit;
    font-size: 10px;
    transition: all 0.15s;
  }}
  .copy-btn:hover {{
    background: var(--bg-hover);
    color: var(--text-primary);
    border-color: var(--border-light);
  }}
  .copy-btn.copied {{
    color: var(--green);
    border-color: var(--green);
  }}

  /* ── Full content view for unchanged passes ── */
  .full-content {{
    overflow-x: auto;
    background: var(--bg-surface);
  }}
  .full-content pre {{
    margin: 0;
    padding: 12px 16px;
    font-family: inherit;
    font-size: 12.5px;
    line-height: 1.65;
