1	"""Interactive pass browser: render the SBlock structure tree after every CUDA
2	lowering pass as a single self-contained HTML file.
3	
4	Left pane is the ordered pass list (click to select). Right pane shows the
5	structure tree for the selected pass, with lines added by that pass highlighted
6	green and lines it removed shown ghosted red — so switching between passes makes
7	"what this pass changed" obvious.
8	
9	Reuses the tree-rendering logic from core.py verbatim; this file only adds
10	per-pass capture, line-level diffing (difflib), and HTML emission.
11	
12	Run with::
13	
14	    python -m tilelang.tools.pass_visualizer.viewer \\
15	        tilelang/tools/pass_visualizer/examples/gemm_relu.py \\
16	        --set M=1024 --set N=1024 --set K=1024 \\
17	        --set block_M=128 --set block_N=128 --set block_K=32 \\
18	        --out gemm_relu_passes.html
19	"""
20	
21	from __future__ import annotations
22	
23	import argparse
24	import contextlib
25	import difflib
26	import html
27	import io
28	import json
29	import os
30	import re
31	
32	from tilelang.engine.semantic_check import PreLowerSemanticCheck
33	
34	from . import core as M
35	
36	# Field names that inspect_structure prints to the LEFT of the "→" arrow.
37	_FIELDS = {
38	    "iter_vars",
39	    "reads",
40	    "writes",
41	    "alloc_buffers",
42	    "match_buffers",
43	    "init?",
44	    "annotations",
45	    "params",
46	    "ret_type",
47	    "buffer_map",
48	    "attrs",
49	}
50	_NODES = ("SBlock", "PrimFunc", "AttrStmt", "SeqStmt", "For", "IfThenElse", "Evaluate", "BufferStore", "SBlockRealize")
51	
52	# Inline styles so highlighting survives even where external CSS classes don't
53	# (some IDE HTML previews strip <style> or sanitize class names).
54	_STY_TILEOP = "background:#ff9d3c;color:#1e1e1e;font-weight:700;padding:0 4px;border-radius:3px"  # tile ops
55	_STY_SYNC = "background:#9d7bff;color:#1e1e1e;font-weight:700;padding:0 4px;border-radius:3px"  # sync primitives
56	_STY_HW = "background:#5fb3d4;color:#1e1e1e;font-weight:600;padding:0 4px;border-radius:3px"  # lowered hw intrinsics
57	_STY_FIELD = "color:#9cdcfe"
58	_STY_NODE = "color:#4ec9b0"
59	_STY_TY = "color:#c586c0"
60	
61	# Op classification. Only genuine operators are highlighted; scalar intrinsics
62	# (max/Cast/bitwise_xor) and DSL constructors (T.Tensor/T.Kernel/T.alloc_*) are
63	# intentionally left plain.
64	#
65	# 1) Tile ops — the authoritative set: every operator registered in C++ via
66	#    TIR_REGISTER_TL_TILE_OP ("tl.tileop.*") in src/op/*.cc. These are the
67	#    high-level tile/fragment operators LowerTileOp consumes. ('region' is a
68	#    TileOperator too but appears as an argument everywhere, so we leave it plain
69	#    to avoid noise.)
70	_TILE_OPS = (
71	    "gemm",
72	    "gemm_sp",
73	    "copy",
74	    "tma_copy",
75	    "fill",
76	    "clear",
77	    "reduce",
78	    "cumsum",
79	    "cummax",
80	    "transpose",
81	    "im2col",
82	    "atomicadd",
83	    "atomic_add",
84	    "atomicmax",
85	    "atomicmin",
86	    "finalize_reducer",
87	)
88	# 2) Synchronization primitives — thread/warp sync emitted by warp-specialization
89	#    and pipelining passes (NOT tile ops).
90	_SYNC_OPS = ("mbarrier_wait_parity", "ptx_arrive_barrier", "mbarrier_expect_tx", "tl_shuffle_elect", "barrier_wait", "fence_barrier_init")
91	# 3) Lowered hardware intrinsics — the PTX/TMA-level result of LowerTileOp.
92	_HW_OPS = ("ptx_mma", "ptx_ldmatrix", "tma_load", "create_tma_descriptor", "tvm_access_ptr", "access_ptr")
93	
94	_TILEOP_RE = re.compile(r"\bT\.(" + "|".join(_TILE_OPS) + r")(?=\(|\s|$)")
95	_SYNC_RE = re.compile(r"\bT\.(" + "|".join(_SYNC_OPS) + r")(?=\(|\s|$)")
96	_HW_RE = re.compile(r"\bT\.(" + "|".join(_HW_OPS) + r")(?=\(|\s|$)")
97	
98	
99	def _highlight(line: str) -> str:
100	    """Server-side syntax highlight one text line into safe HTML with inline styles."""
101	    s = html.escape(line)
102	    # operator highlighting, by class (tile / sync / lowered-hardware)
103	    s = _TILEOP_RE.sub(rf'<span style="{_STY_TILEOP}">T.\1</span>', s)
104	    s = _SYNC_RE.sub(rf'<span style="{_STY_SYNC}">T.\1</span>', s)
105	    s = _HW_RE.sub(rf'<span style="{_STY_HW}">T.\1</span>', s)
106	    # node-type labels
107	    s = re.sub(r"\b(" + "|".join(_NODES) + r")\b", rf'<span style="{_STY_NODE}">\1</span>', s)
108	    # field names (token immediately before the → arrow)
109	    s = re.sub(
110	        r"\b([A-Za-z_?]+)(?=\s*→)", lambda m: f'<span style="{_STY_FIELD}">{m.group(1)}</span>' if m.group(1) in _FIELDS else m.group(0), s
111	    )
112	    # python type annotations after a colon: ":IntImm", ": Array", "[value:Call]"
113	    s = re.sub(r":\s*([A-Z][A-Za-z0-9_]*)\b", rf': <span style="{_STY_TY}">\1</span>', s)
114	    return s
115	
116	
117	def _capture_tree(mod) -> list[str]:
118	    """Render core.inspect_structure(mod) into a list of text lines."""
119	    buf = io.StringIO()
120	    with contextlib.redirect_stdout(buf):
121	        M.inspect_structure(mod)
122	    return buf.getvalue().splitlines()
123	
124	
125	def _diff_rows(prev: list[str], cur: list[str]) -> list[dict]:
126	    """Merge prev->cur into display rows tagged equal / add / del.
127	
128	    'add'  = line present in cur but not prev (this pass introduced it)
129	    'del'  = line present in prev but not cur (this pass removed it; shown ghosted)
130	    'equal'= unchanged carry-over
131	    """
132	    rows: list[dict] = []
133	    sm = difflib.SequenceMatcher(a=prev, b=cur, autojunk=False)
134	    for tag, i1, i2, j1, j2 in sm.get_opcodes():
135	        if tag == "equal":
136	            for line in cur[j1:j2]:
137	                rows.append({"t": "equal", "s": line})
138	        elif tag == "insert":
139	            for line in cur[j1:j2]:
140	                rows.append({"t": "add", "s": line})
141	        elif tag == "delete":
142	            for line in prev[i1:i2]:
143	                rows.append({"t": "del", "s": line})
144	        elif tag == "replace":
145	            for line in prev[i1:i2]:
146	                rows.append({"t": "del", "s": line})
147	            for line in cur[j1:j2]:
148	                rows.append({"t": "add", "s": line})
149	    # Pre-render highlighted HTML + tile-op flag for every row (server-side, so it
150	    # does not depend on browser-side JS or external CSS).
151	    for r in rows:
152	        r["h"] = _highlight(r["s"])
153	        r["op"] = bool(_TILEOP_RE.search(r["s"]))
154	    return rows
155	
