157	def build_pass_data(path: str, factory: str | None, target: str, kwargs: dict[str, object], source: str) -> tuple[str, list[dict]]:
158	    """Run the pipeline pass-by-pass, capturing a tree + diff for each stage.
159	
160	    Returns (kernel_name, stages) where each stage is:
161	        {name, flag, rows}
162	    'flag' is changed/no-op; 'rows' is the diff vs the previous stage's tree.
163	    Stage 0 is the TileLang source; stage 1 the pipeline input ("(input)").
164	    """
165	    module = M.load_user_module(path)
166	
167	    if factory is not None:
168	        if not hasattr(module, factory):
169	            raise SystemExit(f"Name {factory!r} not found in {path}.")
170	        kernels = {factory: getattr(module, factory)}
171	    else:
172	        kernels = M.discover_jit_kernels(module)
173	        if not kernels:
174	            raise SystemExit(f"No @tilelang.jit kernel found in {path}. For a bare @T.prim_func factory, pass --factory NAME.")
175	
176	    # The viewer focuses on a single kernel; take the first discovered one.
177	    name, kernel = next(iter(kernels.items()))
178	    func = M.kernel_to_tir(kernel, **kwargs)
179	    mod, resolved_target = M.build_module(func, target=target)
180	
181	    PreLowerSemanticCheck(mod)
182	    stages = M.build_pass_stages(resolved_target)
183	
184	    captured: list[dict] = []
185	
186	    # Stage 0: the TileLang source itself, shown in the same right-hand pane.
187	    # Rows are plain (no diff) but still tile-op highlighted.
188	    src_rows = [{"t": "equal", "s": ln, "h": _highlight(ln), "op": bool(_TILEOP_RE.search(ln))} for ln in source.split("\n")]
189	    captured.append({"name": "source code", "flag": "source", "rows": src_rows})
190	
191	    prev_lines: list[str] = []
192	    input_lines = _capture_tree(mod)
193	    captured.append(
194	        {
195	            "name": "(input)",
196	            "flag": "input",
197	            "rows": _diff_rows([], input_lines),
198	        }
199	    )
200	    prev_lines = input_lines
201	
202	    for idx, (pname, transform) in enumerate(stages, start=1):
203	        before = str(mod)
204	        with resolved_target:  # post-LayoutInference passes need Target.Current()
205	            mod = transform(mod)
206	        after = str(mod)
207	        changed = before != after
208	
209	        cur_lines = _capture_tree(mod)
210	        captured.append(
211	            {
212	                "name": f"[{idx:02d}] {pname}",
213	                "flag": "changed" if changed else "no-op",
214	                "rows": _diff_rows(prev_lines, cur_lines),
215	            }
216	        )
217	        prev_lines = cur_lines
218	
219	    return name, captured
