313	    <div class="sub" id="h-sub"></div>
314	    <div class="legend">
315	      <span><i class="sw add"></i>added by this pass</span>
316	      <span><i class="sw del"></i>removed by this pass</span>
317	      <span><i class="sw tileop"></i>tile op</span>
318	      <span><i class="sw sync"></i>sync primitive</span>
