325	<script>
326	const DATA = __DATA__;
327	let cur = 0;
328	
329	function escapeHtml(s) {
330	  return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
331	}
332	
333	function countDelta(stage) {
334	  let a = 0, d = 0;
335	  for (const r of stage.rows) { if (r.t === 'add') a++; else if (r.t === 'del') d++; }
336	  return [a, d];
337	}
338	
339	function renderList() {
340	  const el = document.getElementById('passlist');
341	  el.innerHTML = '';
342	  DATA.forEach((st, i) => {
343	    const [a, d] = countDelta(st);
344	    const row = document.createElement('div');
345	    row.className = 'pass' + (i === cur ? ' sel' : '');
346	    row.onclick = () => select(i);
347	    const delta = (st.flag === 'changed') ? `<span class="delta">+${a} -${d}</span>` : '';
348	    row.innerHTML = `<span class="nm">${escapeHtml(st.name)}</span>`
349	      + `<span class="badge ${st.flag}">${st.flag}</span>` + delta;
350	    el.appendChild(row);
351	  });
352	}
353	
354	function renderTree() {
355	  const st = DATA[cur];
356	  const [a, d] = countDelta(st);
357	  document.getElementById('h-title').textContent = st.name;
358	  document.getElementById('h-sub').textContent =
359	    st.flag === 'source' ? 'original TileLang source'
360	    : st.flag === 'input' ? 'pipeline input (before any pass)'
361	    : `${st.flag} — ${a} line(s) added, ${d} line(s) removed vs previous pass`;
362	  const pre = document.getElementById('tree');
363	  pre.innerHTML = '';
364	  for (const r of st.rows) {
365	    const span = document.createElement('span');
366	    const cls = r.t === 'add' ? 'add' : r.t === 'del' ? 'del' : '';
367	    // r.h = server-side highlighted HTML; r.op = line carries a tile-op call.
368	    span.className = 'row' + (cls ? ' ' + cls : '') + (r.op ? ' tileop-row' : '');
369	    const mark = r.t === 'add' ? '+' : r.t === 'del' ? '-' : ' ';
370	    span.innerHTML = `<span class="mk">${mark}</span>${r.h}`;
371	    pre.appendChild(span);
372	  }
373	}
