375	function select(i) {
376	  cur = Math.max(0, Math.min(DATA.length - 1, i));
377	  renderList();
378	  renderTree();
379	  const sel = document.querySelector('.pass.sel');
380	  if (sel) sel.scrollIntoView({block: 'nearest'});
381	}
382	
383	document.addEventListener('keydown', (e) => {
384	  if (e.key === 'ArrowDown') { select(cur + 1); e.preventDefault(); }
385	  else if (e.key === 'ArrowUp') { select(cur - 1); e.preventDefault(); }
386	});
387	
388	// Click the "Passes" header to collapse / expand the left panel.
389	document.getElementById('passhdr').onclick = () => {
390	  const left = document.getElementById('left');
391	  const collapsed = left.classList.toggle('collapsed');
392	  left.querySelector('.arrow').innerHTML = collapsed ? '&#9654;' : '&#9664;';
393	};
394	
395	renderList();
396	renderTree();
397	</script>
398	</body>
399	</html>
400	"""
401	
402	
403	def emit_html(title: str, stages: list[dict]) -> str:
404	    # Escape "</" so embedded row text containing "</script>" cannot terminate
405	    # the <script> block early and inject HTML/JS into the report.
406	    data_json = json.dumps(stages).replace("</", "<\\/")
407	    out = HTML_TEMPLATE.replace("__TITLE__", html.escape(title))
408	    out = out.replace("__DATA__", data_json)
409	    return out
