411	
412	def emit_txt(title: str, stages: list[dict]) -> str:
413	    """Plain-text rendering: each stage's tree, one stage after another.
414	
415	    Uses the raw row text (`s`), with a +/- marker for diff rows so the same
416	    information shown in the HTML is greppable / diffable as text.
417	    """
418	    lines: list[str] = [f"########## kernel: {title} ##########", ""]
419	    for st in stages:
420	        lines.append(f"===== {st['name']}  [{st['flag']}] =====")
421	        for r in st["rows"]:
422	            mark = "+" if r["t"] == "add" else "-" if r["t"] == "del" else " "
423	            lines.append(f"{mark} {r['s']}")
424	        lines.append("")
425	    return "\n".join(lines)
