428	def _write_outputs(name: str, stages: list[dict], html_path: str) -> str:
429	    """Write the HTML and a sibling .txt; return the txt path."""
430	    os.makedirs(os.path.dirname(os.path.abspath(html_path)), exist_ok=True)
